// src/gfa/linkKey.ts
var flip = (strand) => strand === "-" ? "+" : "-";
var side = (strand) => strand === "-" ? "-" : "+";
function linkKey(source, strand1, target, strand2) {
  const stated = `${source}	${side(strand1)}	${target}	${side(strand2)}`;
  const turned = `${target}	${flip(strand2)}	${source}	${flip(strand1)}`;
  return stated < turned ? stated : turned;
}

export {
  linkKey
};
